2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	
5	import '../../domain/repositories/account_settings_repository.dart';
6	
7	/// Drives [AccountSettingsScreen]: just the one toggle's current value
8	/// (mirrored straight from [AccountSettingsRepository.biometricEnabledStream]
9	/// — the repository is the single source of truth, Boundaries) plus an
10	/// inline error message for a failed toggle.
11	class AccountSettingsState {
12	  const AccountSettingsState({
13	    required this.biometricEnabled,
14	    this.errorMessage,
15	    this.isSaving = false,
16	  });
17	
18	  final bool biometricEnabled;
19	
20	  /// Set only once [AccountSettingsCubit.toggleBiometric]'s own PATCH call
21	  /// fails — the switch itself has already reverted via the repository's
22	  /// own stream by the time this is shown (I/O matrix: "Toggle fails ->
23	  /// switch reverts ... Failure.message shown inline").
24	  final String? errorMessage;
25	
26	  /// Review finding: `true` for the duration of one [toggleBiometric] call
27	  /// — `account_settings_screen.dart` disables the `Switch` while this is
28	  /// `true`, so a double-tap can never start a second, overlapping
29	  /// `setBiometricEnabled` call in the first place (the repository's own
30	  /// generation guard is the backstop for every other overlap this can't
31	  /// prevent, e.g. a boot fetch racing a toggle).
32	  final bool isSaving;
33	
34	  AccountSettingsState copyWith({
35	    bool? biometricEnabled,
36	    String? errorMessage,
37	    bool clearErrorMessage = false,
38	    bool? isSaving,
39	  }) {
40	    return AccountSettingsState(
41	      biometricEnabled: biometricEnabled ?? this.biometricEnabled,
42	      errorMessage: clearErrorMessage
43	          ? null
44	          : (errorMessage ?? this.errorMessage),
45	      isSaving: isSaving ?? this.isSaving,
46	    );
47	  }
48	
49	  @override
50	  bool operator ==(Object other) =>
51	      identical(this, other) ||
52	      (other is AccountSettingsState &&
53	          other.biometricEnabled == biometricEnabled &&
54	          other.errorMessage == errorMessage &&
55	          other.isSaving == isSaving);
56	
57	  @override
58	  int get hashCode => Object.hash(biometricEnabled, errorMessage, isSaving);
59	
60	  @override
61	  String toString() =>
62	      'AccountSettingsState(biometricEnabled: $biometricEnabled, '
63	      'errorMessage: $errorMessage, isSaving: $isSaving)';
64	}
65	
66	/// Calls [AccountSettingsRepository] directly (no use-case — same small-
67	/// scope rationale `AuthCubit`'s own doc gives). [toggleBiometric] is the
68	/// I/O matrix's optimistic flip/revert, end to end: the repository itself
69	/// flips [AccountSettingsRepository.currentBiometricEnabled] immediately
70	/// and emits it on [AccountSettingsRepository.biometricEnabledStream] —
71	/// this cubit only mirrors that stream into its own [AccountSettingsState]
72	/// (subscribed once, at construction) and separately layers the
73	/// toggle-failure error message on top.
74	class AccountSettingsCubit extends Cubit<AccountSettingsState> {
75	  AccountSettingsCubit(this._repository)
76	    : super(
77	        AccountSettingsState(
78	          biometricEnabled: _repository.currentBiometricEnabled,
79	        ),
80	      ) {
81	    _subscription = _repository.biometricEnabledStream.listen((value) {
82	      // Review finding: `biometricEnabledStream`'s first delivery always
83	      // replays the exact same value the constructor above just read
84	      // synchronously — without this check, that replay was a redundant
85	      // duplicate emission (not skipped by `Cubit`'s own equal-state dedup,
86	      // which only applies once something has already been emitted),
87	      // forcing one pointless extra rebuild right after every screen mount.
88	      if (value == state.biometricEnabled) {
89	        return;
90	      }
91	      emit(state.copyWith(biometricEnabled: value));
92	    });
93	  }
94	
95	  final AccountSettingsRepository _repository;
96	  late final StreamSubscription<bool> _subscription;
97	
98	  Future<void> toggleBiometric(bool value) async {
99	    emit(state.copyWith(clearErrorMessage: true, isSaving: true));
100	    final result = await _repository.setBiometricEnabled(value);
101	    // Review finding: this cubit is a `get_it` lazy singleton with
102	    // `dispose: (cubit) => cubit.close()` — if `close()` runs while the
103	    // `await` above is still pending (e.g. `resetCoreDependencies()`
104	    // during a logout, once Epic 8 implements one), `emit()` below would
105	    // otherwise throw a `StateError` ("Cannot emit new states after
106	    // calling close"), unlike the repository-layer `_emit` methods in this
107	    // codebase, which already guard against the equivalent race.
108	    if (isClosed) {
109	      return;
110	    }
111	    result.match((failure) {
112	      // Review finding: a superseded call's `Left` is an internal
113	      // control-flow signal (`AccountSettingsRepository.
114	      // supersededMessage`), not a real error — the winning call already
115	      // settled the value correctly, so nothing should be shown; showing
116	      // `failure.message` unconditionally leaked that raw, English,
117	      // internal string into this otherwise fully Portuguese screen.
118	      if (failure.message == AccountSettingsRepository.supersededMessage) {
119	        emit(state.copyWith(isSaving: false));
120	        return;
121	      }
122	      emit(state.copyWith(errorMessage: failure.message, isSaving: false));
123	    }, (_) => emit(state.copyWith(isSaving: false)));
124	  }
125	
126	  /// Review finding: [errorMessage] previously cleared only at the start of
127	  /// the *next* [toggleBiometric] call — since this cubit is a DI
128	  /// singleton that outlives any single Configurações visit, a failed
129	  /// toggle's error text would otherwise still be showing if the user
130	  /// left the screen and came back later with no new attempt made.
131	  /// `account_settings_screen.dart` calls this once, on mount, same
132	  /// "stale message must not linger unchanged" fix already applied to
133	  /// `vault_lock_screen.dart`'s own PIN-mismatch error, just anchored to
134	  /// screen-entry instead of attempt-start.
135	  void clearStaleError() {
136	    if (state.errorMessage != null) {
137	      emit(state.copyWith(clearErrorMessage: true));
138	    }
139	  }
140	
141	  @override
142	  Future<void> close() async {
143	    await _subscription.cancel();
144	    return super.close();
145	  }
146	}
