5	/// `PATCH /account/settings`'s response `data` object
6	/// (`openapi.yaml:1764-1803`) carries `id`/`email`/`displayName`/`persona`/
7	/// `biometricEnabled`/`serverRevision`/`createdAt`/`updatedAt` — this DTO
8	/// decodes only [biometricEnabled] (Code Map), the single field Story 2.4
9	/// needs; every other field is simply ignored by `json_serializable`'s
10	/// generated `fromJson` rather than modeled here (`displayName`/`persona`
11	/// are Epic 8's scope — Boundaries: "never touched").
12	@JsonSerializable()
13	class AccountSettingsDto {
14	  const AccountSettingsDto({required this.biometricEnabled});
15	
16	  final bool biometricEnabled;
17	
18	  factory AccountSettingsDto.fromJson(Map<String, dynamic> json) =>
19	      _$AccountSettingsDtoFromJson(json);
20	
21	  Map<String, dynamic> toJson() => _$AccountSettingsDtoToJson(this);
22	}
