3	/// `AuthRepository.signUp`/`logIn` on success (RNF06 — domain, no
4	/// `flutter`/`data/` import).
5	class AuthenticatedUser {
6	  const AuthenticatedUser({required this.id, required this.email});
7	
8	  final String id;
9	  final String email;
10	
11	  @override
12	  bool operator ==(Object other) =>
13	      identical(this, other) ||
14	      (other is AuthenticatedUser && other.id == id && other.email == email);
15	
16	  @override
17	  int get hashCode => Object.hash(id, email);
18	
19	  @override
20	  String toString() => 'AuthenticatedUser(id: $id, email: $email)';
21	}
